INSERT INTO `website_profil` VALUES 
('1', 'Madrasah Digital dan Berkarakter', 'MAN 3 Banjar berkomitmen menghadirkan pendidikan yang memadukan ilmu pengetahuan, nilai keislaman, teknologi, dan pelayanan yang transparan.', 'Terwujudnya madrasah yang unggul dalam prestasi, berakhlak mulia, dan berwawasan teknologi.', 'Menyelenggarakan pendidikan yang berkualitas, membentuk karakter islami, mengembangkan potensi siswa, dan meningkatkan layanan berbasis digital.', 'Meningkatkan mutu pendidikan, pelayanan, prestasi, dan tata kelola madrasah.', 'Jl. A. Yani No.Km. 15.200, Gambut, Kec. Gambut, Kabupaten Banjar, Kalimantan Selatan 70652', '08xxxxxx', 'man.tigabjr@gmail.com', '2026-09-26 12:32:48', 'Sejarah Singkat MAN 3 Banjar\r\nPerjalanan MAN 3 Banjar memiliki sejarah yang cukup panjang dan telah mengalami beberapa kali perubahan status serta nama sebelum akhirnya dikenal dengan nama saat ini. Berikut adalah kronologinya:\r\n\r\n1958 – 1969: Madrasah ini bermula sebagai Yayasan Pendidikan Sinar Harapan. Kegiatan belajar mengajar dimulai pada rentang tahun 1958-1960 di bawah pimpinan H. Hasan sebagai kepala madrasah yang pertama.\r\n\r\n1970 – 1977: Lembaga pendidikan ini berubah nama menjadi PGAN (Pendidikan Guru Agama Negeri).\r\n\r\n1978: Terjadi alih fungsi menjadi MAN Gambut, berdasarkan Surat Keputusan Direktur Jenderal Binbaga Islam Departemen Agama RI Nomor: E.IV/PP.00.6/Kep/17.A/1978.\r\n\r\n1996: Berdasarkan keputusan Kepala Kantor Wilayah Departemen Agama Provinsi Kalimantan Selatan, nama MAN Gambut berubah menjadi MAN 1 Martapura.\r\n\r\n2016 – Sekarang: Melalui Surat Keputusan Menteri Agama Republik Indonesia Nomor 671 tentang Perubahan Nama Madrasah Aliyah Negeri di Provinsi Kalimantan Selatan, MAN 1 Martapura resmi berubah nama menjadi MAN 3 Banjar hingga saat ini.', '', '', '', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d4765.802898583569!2d114.67185177497234!3d-3.4137733965607673!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2de69d70e1cc07ed%3A0x56b455113188c315!2sMAN%203%20BANJAR%20%2F%20MAN%201%20MARTAPURA%20GAMBUT!5e1!3m2!1sid!2sid!4v1781481435828!5m2!1sid!2sid', '', '', '', '', 'Senin - Kamis: 07:30 - 15:30 Jumat: 07:30 - 16:00 Sabtu - Minggu: Tutup', 'https://rdm.man3banjar.sch.id/', '131163030003', '30315526', 'MADRASAH DIGITAL UNGGULAN', 'Mewujudkan Generasi Islami, Berkarakter & Unggul Digital', 'Selamat datang di portal informasi dan pusat layanan terpadu MAN 3 Banjar. Menghadirkan ekosistem pembelajaran modern, transparan, dan berlandaskan akhlakul karimah.', 'Pendaftaran PMB Online', 'pmb', 'Jelajahi Profil Madrasah', 'website/sejarah', 'Sambutan Kepala Madrasah', 'Assalamu’alaikum Warahmatullahi Wabarakatuh.\r\n\r\nPuji syukur kita panjatkan ke hadirat Allah SWT atas limpahan rahmat dan karunia-Nya. Selamat datang di portal resmi Madrasah Aliyah Negeri 3 Banjar.\r\n\r\nDi era disrupsi teknologi saat ini, MAN 3 Banjar terus bertransformasi mengintegrasikan pendidikan ilmu agama yang kokoh, penguasaan sains dan teknologi, serta pembinaan akhlak mulia. Kami berkomitmen memberikan layanan pendidikan terbaik yang transparan dan adaptif bagi seluruh peserta didik dan masyarakat.', 'Nor Ifansyah, S.Pd., M.Sc', 'Kepala MAN 3 Banjar', 'f5eda9553e95e468aab081e283b122b8.png');
