INSERT INTO `berita` VALUES 
('15', 'Hari Kemerdekaan Indonesia', 'hari-kemerdekaan-indonesia', '2', '2026-06-11 23:58:49', 'Kegiatan', '0', '0', NULL, 'Amuntai (MAN 2 HSU) – MAN 2 HSU kembali menggelar kegiatan tahunan bertajuk SWARNABHASA MAN FEST 2026 yang berlangsung mulai tanggal 10 hingga 18 Juni 2026 di lingkungan MAN 2 HSU. Kegiatan ini menjadi ajang bagi peserta didik untuk menyalurkan bakat, minat, kreativitas, serta semangat sportivitas melalui berbagai perlombaan yang menarik dan edukatif. Rabu (10/06/2026).\r\n\r\nSWARNABHASA MAN FEST 2026 menghadirkan beragam cabang lomba yang diikuti oleh siswa-siswi MAN 2 HSU. Adapun perlombaan yang digelar antara lain Futsal, Voli, Tenis Meja (Ping Pong), Video Kreatif, Mobile Legends, Catur, Tarik Tambang, serta berbagai lomba seni dan keterampilan lainnya. Seluruh rangkaian kegiatan berlangsung meriah dengan antusiasme tinggi dari para peserta maupun warga madrasah.\r\n\r\nKetua panitia kegiatan menyampaikan bahwa SWARNABHASA MAN FEST tidak hanya menjadi sarana kompetisi, tetapi juga wadah untuk mempererat silaturahmi, menumbuhkan jiwa kepemimpinan, kerja sama tim, serta mengembangkan potensi peserta didik di bidang akademik maupun nonakademik.\r\n\r\nPlt. Kepala MAN 2 HSU , Irwan dalam tanggapannya mengapresiasi terselenggaranya kegiatan tersebut. Menurutnya, SWARNABHASA MAN FEST 2026 merupakan salah satu bentuk komitmen madrasah dalam mendukung pengembangan karakter dan potensi peserta didik secara menyeluruh.\r\n\"Kegiatan SWARNABHASA MAN FEST 2026 menjadi momentum yang sangat baik bagi siswa untuk mengekspresikan bakat, kreativitas, dan kemampuan yang mereka miliki. Kami berharap melalui kegiatan ini lahir generasi yang tidak hanya unggul dalam bidang akademik, tetapi juga memiliki karakter yang kuat, sportif, kreatif, dan mampu berkolaborasi dengan baik. Terima kasih kepada seluruh panitia, guru, dan peserta yang telah berpartisipasi sehingga kegiatan ini dapat terlaksana dengan lancar dan meriah.\" Kata Irwan.\r\n\r\nMelalui SWARNABHASA MAN FEST 2026, MAN 2 HSU berharap dapat terus menciptakan lingkungan pendidikan yang aktif, inovatif, dan inspiratif, sekaligus menjadi wadah bagi peserta didik untuk mengembangkan potensi diri serta meraih berbagai prestasi di masa depan.', 'd30125d213a463278f30ba9e1f01e3b4.png', 'Draft', NULL, '2026-05-23 11:50:18', 'pamflet-berita-15-1781219161.jpg', '2026-06-12 01:06:01', 'cover', 'top', 'auto'),
